function renderOrders(){document.querySelector('#order-board').innerHTML=orders.map(([title,items],column)=>`<div class="order-col"><h3>${title} · ${items.length}</h3>${items.map((x,i)=>{const total=x[5]||estimateOrderTotal(x[2]);return`<article class="order-card"><header><strong>${x[0]} · ${x[1]}</strong><small>${x[3]}</small></header><p>${x[2]}</p><footer><b>฿${money(total)}</b><span><button class="order-edit-btn" data-column="${column}" data-index="${i}">แก้ไข</button><button class="checkout-btn" data-column="${column}" data-index="${i}">คิดเงิน</button></span></footer></article>`}).join('')}</div>`).join('');document.querySelectorAll('.checkout-btn').forEach(b=>b.onclick=()=>openCheckout(+b.dataset.column,+b.dataset.index));document.querySelectorAll('.order-edit-btn').forEach(b=>b.onclick=()=>openEditOrder(+b.dataset.column,+b.dataset.index))}
function estimateOrderTotal(text){let total=0;String(text).split(',').forEach(part=>{const name=part.split('×')[0].trim(),qty=+(part.split('×')[1]||1),menu=recipes.find(x=>x.name===name);total+=(+menu?.selling_price||50)*qty});return total}
