function menuMainType(item){const text=`${item.category||''} ${item.code||''}`.toLowerCase();return /(เครื่องดื่ม|กาแฟ|ชา|โกโก้|นม|โซดา|สมูท|drink|coffee|tea|cocoa)/i.test(text)?'drink':'food'}
function refreshMenuCategoryOptions(){const select=document.querySelector('#menu-category-filter');if(!select)return;const categories=[...new Set(recipes.filter(x=>menuTypeFilter==='all'||menuMainType(x)===menuTypeFilter).map(x=>x.category||'ไม่ระบุประเภท'))].sort((a,b)=>a.localeCompare(b,'th'));if(menuCategoryFilter&&!categories.includes(menuCategoryFilter))menuCategoryFilter='';select.innerHTML='<option value="">ทุกหมวดย่อย</option>'+categories.map(x=>`<option value="${x.replaceAll('"','&quot;')}">${x}</option>`).join('');select.value=menuCategoryFilter}
function renderRecipes(data=recipes){
 refreshMenuCategoryOptions();
 const counts={food:recipes.filter(x=>menuMainType(x)==='food').length,drink:recipes.filter(x=>menuMainType(x)==='drink').length};document.querySelector('#menu-count-all').textContent=recipes.length;document.querySelector('#menu-count-food').textContent=counts.food;document.querySelector('#menu-count-drink').textContent=counts.drink;
 const q=menuSearchText.trim().toLowerCase();data=data.filter(x=>(menuTypeFilter==='all'||menuMainType(x)===menuTypeFilter)&&(!menuCategoryFilter||(x.category||'ไม่ระบุประเภท')===menuCategoryFilter)&&(!q||`${x.name} ${x.code||''} ${x.category||''}`.toLowerCase().includes(q)));
 document.querySelector('#menu .table-panel thead').innerHTML='<tr><th>เมนู</th><th>ราคาหน้าร้าน</th><th>ราคาออนไลน์</th><th>สูตรต่อ 1 เสิร์ฟ</th><th>สถานะการขาย</th></tr>';
 document.querySelector('#menu .table-note').textContent='เมนูที่ตั้งเป็น Sold out จะไม่แสดงในรายการเลือกเมนูของ POS';
 if(!data.length)document.querySelector('#recipes').innerHTML=`<tr><td colspan="5"><div class="menu-empty">${menuLoadError?`<strong>โหลดรายการเมนูไม่สำเร็จ</strong><span>${menuLoadError}</span><button id="retry-menu-load">ลองโหลดอีกครั้ง</button>`:'ไม่พบเมนูที่ตรงกับการค้นหา'}</div></td></tr>`;
 else{const groups=menuTypeFilter==='all'?[['food','อาหารหลัก'],['drink','เครื่องดื่ม']]:[[menuTypeFilter,menuTypeFilter==='drink'?'เครื่องดื่ม':'อาหารหลัก']];document.querySelector('#recipes').innerHTML=groups.map(([type,label])=>{const rows=data.filter(x=>menuMainType(x)===type);if(!rows.length)return'';return `<tr class="menu-group-row ${type}"><td colspan="5"><span>${type==='drink'?'🥤':'🍜'}</span><strong>${label}</strong><b>${rows.length} เมนู</b></td></tr>`+rows.map(x=>`<tr class="staff-menu-row ${x.sold_out?'is-soldout':''}" data-menu-row="${x.recipe_id||x.id}"><td><strong>${x.name}</strong><small><span class="menu-category-pill ${type}">${x.category||'ไม่ระบุประเภท'}</span> ${x.code||x.serving_size||''}</small></td><td><strong class="staff-price">฿${money(x.selling_price)}</strong></td><td><strong class="staff-price online">฿${money(x.online_selling_price)}</strong></td><td><button class="view-staff-recipe" data-id="${x.recipe_id||x.id}">▤ ดูสูตร</button></td><td><button class="availability-toggle ${x.sold_out?'soldout':'available'}" data-id="${x.recipe_id||x.id}" data-sold-out="${x.sold_out?'true':'false'}"><i></i>${x.sold_out?'Sold out':'พร้อมขาย'}</button></td></tr><tr class="staff-recipe-detail hidden" id="staff-recipe-${x.recipe_id||x.id}"><td colspan="5"><div class="staff-recipe-loading">กำลังโหลดสูตร...</div></td></tr>`).join('')}).join('')}
 document.querySelectorAll('.view-staff-recipe').forEach(b=>b.onclick=()=>toggleStaffRecipe(b));document.querySelectorAll('.availability-toggle').forEach(b=>b.onclick=()=>toggleRecipeAvailability(b));const retry=document.querySelector('#retry-menu-load');if(retry)retry.onclick=loadData;
}
