async function toggleStaffRecipe(button){const id=button.dataset.id,row=document.querySelector(`#staff-recipe-${id}`),opening=row.classList.contains('hidden');document.querySelectorAll('.staff-recipe-detail').forEach(x=>x.classList.add('hidden'));document.querySelectorAll('.view-staff-recipe').forEach(x=>x.textContent='▤ ดูสูตร');if(!opening)return;row.classList.remove('hidden');button.textContent='▴ ซ่อนสูตร';try{const r=await fetch(`/api/recipes/${id}`);if(!r.ok)throw Error();const detail=await r.json();row.querySelector('td').innerHTML=`<div class="staff-recipe-sheet"><div><span>สูตรมาตรฐาน</span><h4>${detail.recipe.name}</h4><p>${detail.recipe.serving_size||'1 เสิร์ฟ'}</p></div><div class="staff-ingredients">${detail.items.length?detail.items.map((x,i)=>`<div><b>${i+1}</b><span>${x.name}</span><strong>${money(x.qty_base)} ${x.base_unit}</strong></div>`).join(''):'<p>ยังไม่ได้กำหนดวัตถุดิบในสูตร</p>'}</div></div>`}catch{row.querySelector('td').innerHTML='<div class="staff-recipe-loading">โหลดสูตรไม่สำเร็จ กรุณาลองใหม่</div>'}}
async function toggleRecipeAvailability(button){const id=button.dataset.id,soldOut=button.dataset.soldOut!=='true';button.disabled=true;try{const r=await fetch(`/api/recipes/${id}/availability`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({sold_out:soldOut})});if(!r.ok)throw Error();const item=recipes.find(x=>String(x.recipe_id||x.id)===id);if(item)item.sold_out=soldOut;renderRecipes();refreshOptions();toast(soldOut?'ตั้งเมนูเป็น Sold out แล้ว':'เปิดขายเมนูแล้ว ✓')}catch{toast('เปลี่ยนสถานะเมนูไม่ได้ กรุณาตรวจสอบเซิร์ฟเวอร์')}finally{button.disabled=false}}
const recipeTooltip=document.querySelector('#recipe-tooltip');
async function getRecipeDetail(id){
 const menu=recipes.find(x=>String(x.recipe_id||x.id)===String(id));let items=menu?.items||[];
 if(Number.isInteger(+id)){try{const res=await fetch(`/api/recipes/${id}`);if(res.ok)items=(await res.json()).items}catch{}}
 return{menu,items:items.map(item=>{const ing=ingredients.find(x=>String(x.id)===String(item.ingredient_id));return{name:item.name||ing?.name||'วัตถุดิบ',qty:item.qty_base,unit:item.base_unit||ing?.base_unit||''}})};
}
async function showRecipeTooltip(id,event){
 const {menu,items}=await getRecipeDetail(id);recipeTooltip.innerHTML=`<h4>${menu?.name||'สูตรเมนู'}</h4><p>สูตรต่อ 1 เสิร์ฟ</p>${items.length?items.map(x=>`<div class="tooltip-ingredient"><span>${x.name}</span><b>${money(x.qty)} ${x.unit}</b></div>`).join(''):'<div class="tooltip-empty">ยังไม่ได้กำหนดวัตถุดิบในสูตร</div>'}`;recipeTooltip.classList.add('show');recipeTooltip.setAttribute('aria-hidden','false');moveRecipeTooltip(event);
}
function moveRecipeTooltip(event){const pad=14,w=290,h=recipeTooltip.offsetHeight||200,x=Math.min((event.clientX||100)+16,innerWidth-w-pad),y=Math.min((event.clientY||100)+16,innerHeight-h-pad);recipeTooltip.style.left=`${Math.max(pad,x)}px`;recipeTooltip.style.top=`${Math.max(pad,y)}px`}
function hideRecipeTooltip(){recipeTooltip.classList.remove('show');recipeTooltip.setAttribute('aria-hidden','true')}
