 document.querySelectorAll('[data-ingredient-group]').forEach(button=>button.onclick=()=>{document.querySelector('#ingredient-browser').dataset.group=button.dataset.ingredientGroup;renderIngredients()});
 document.querySelector('#ingredient-search').oninput=renderIngredients;
