function renderIngredients(){
 setupIngredientBrowser();
 const groupLabels={A:'ของสด',B:'ของแช่เย็น',C:'ของแห้ง',D:'บรรจุภัณฑ์'},query=document.querySelector('#ingredient-search').value.trim().toLowerCase(),group=document.querySelector('#ingredient-browser').dataset.group||'';
 document.querySelectorAll('[data-ingredient-group]').forEach(button=>{const value=button.dataset.ingredientGroup;button.classList.toggle('active',value===group);button.querySelector('b').textContent=ingredients.filter(x=>!value||x.stock_group===value).length});
 const visibleIngredients=ingredients.filter(x=>(!group||x.stock_group===group)&&(!query||`${x.name} ${x.sku} ${x.supplier||''}`.toLowerCase().includes(query)));
 document.querySelector('#ingredients').innerHTML=ingredients.map(x=>{const low=+x.stock_qty<=+x.reorder_level,expiry=x.expiry_date?new Date(x.expiry_date).toLocaleDateString('th-TH'):'-',days=x.expiry_date?(new Date(x.expiry_date)-new Date())/864e5:9999;return `<tr class="${low?'low-stock-row':''}"><td>${x.sku}<small class="stock-sub">${x.barcode||'ไม่มี Barcode'}</small></td><td><strong>${x.name}</strong></td><td><strong>${money(x.stock_qty)}</strong> ${x.base_unit}</td><td>${money(x.reorder_level)} ${x.base_unit}</td><td>฿${money(x.cost_per_base_unit)}</td><td>${x.supplier||'-'}</td><td class="${days<30?'expiry-soon':''}">${expiry}</td><td><span class="pill ${low?'low':''}">${low?'⚠ ควรสั่งซื้อ':'ปกติ'}</span></td><td><button class="edit-stock" data-stock-id="${x.id}" aria-label="แก้ไข ${x.name}">✎</button></td></tr>`}).join('');
 const visibleIds=new Set(visibleIngredients.map(x=>String(x.id)));
 document.querySelectorAll('#ingredients tr').forEach(row=>{const id=row.querySelector('.edit-stock').dataset.stockId,item=ingredients.find(x=>String(x.id)===id);row.hidden=!visibleIds.has(id);row.cells[1].insertAdjacentHTML('beforeend',`<small class="stock-sub">${groupLabels[item.stock_group]||'ยังไม่จัดกลุ่ม'}</small>`)});
 if(!visibleIngredients.length)document.querySelector('#ingredients').insertAdjacentHTML('beforeend','<tr><td colspan="9" class="menu-empty">ไม่พบวัตถุดิบในประเภทหรือคำค้นนี้</td></tr>');
 document.querySelectorAll('.edit-stock').forEach(b=>b.onclick=()=>openStockForm(b.dataset.stockId));refreshStockOptions();
}
function renderStockHistory(){
 const labels={OPENING:'ยอดตั้งต้น',PURCHASE:'รับสินค้า',USE:'เบิกใช้',ADJUST_IN:'ปรับเพิ่ม',ADJUST_OUT:'ปรับลด',WASTE:'ของเสีย'},incoming=['OPENING','PURCHASE','ADJUST_IN'];
 document.querySelector('#stock-history').innerHTML=stockHistory.length?stockHistory.map(x=>{const positive=incoming.includes(x.txn_type),sign=positive?'+':'−';return `<tr><td>${new Date(x.txn_at).toLocaleString('th-TH',{dateStyle:'short',timeStyle:'short'})}</td><td><strong>${x.name}</strong><small class="stock-sub">${x.sku}</small></td><td><span class="movement-pill ${positive?'movement-in':x.txn_type==='WASTE'?'movement-waste':'movement-out'}">${labels[x.txn_type]||x.txn_type}</span></td><td class="movement-qty ${positive?'up':'down'}">${sign}${money(x.qty_base)} ${x.base_unit}</td><td>${x.reference||'-'}</td><td>${x.note||'-'}</td></tr>`}).join(''):'<tr><td colspan="6">ไม่พบประวัติการเคลื่อนไหว</td></tr>';
 document.querySelector('#history-in').textContent=`${stockHistory.filter(x=>incoming.includes(x.txn_type)).length} รายการ`;
 document.querySelector('#history-out').textContent=`${stockHistory.filter(x=>['USE','ADJUST_OUT'].includes(x.txn_type)).length} รายการ`;
 document.querySelector('#history-waste').textContent=`${stockHistory.filter(x=>x.txn_type==='WASTE').length} รายการ`;
}
async function loadStockHistory(){
 const params=new URLSearchParams({limit:'100'}),ingredient=document.querySelector('#history-ingredient').value,type=document.querySelector('#history-type').value;if(ingredient)params.set('ingredient_id',ingredient);if(type)params.set('txn_type',type);
 try{const res=await fetch(`/api/stock/transactions?${params}`);if(res.ok)stockHistory=await res.json()}catch{}renderStockHistory();
}
async function fetchMasterData(){let lastError;for(let attempt=0;attempt<2;attempt++){try{const [r,i]=await Promise.all([fetch('/api/recipes',{cache:'no-store'}),fetch('/api/ingredients',{cache:'no-store'})]);if(!r.ok||!i.ok)throw Error(`API ${r.status}/${i.status}`);return{recipes:await r.json(),ingredients:await i.json()}}catch(error){lastError=error;if(!attempt)await new Promise(resolve=>setTimeout(resolve,600))}}throw lastError}
async function loadData(){
 try{const data=await fetchMasterData();recipes=data.recipes;ingredients=data.ingredients;menuLoadError=''}catch(error){recipes=[];ingredients=[];menuLoadError='ไม่สามารถเชื่อมต่อฐานข้อมูล กรุณาตรวจสอบว่าเซิร์ฟเวอร์เปิดอยู่';console.error('Master data load failed',error)}
 renderRecipes();renderIngredients();refreshOptions();renderProfitAnalysis();refreshPurchaseOptions();document.querySelector('#history-ingredient').innerHTML='<option value="">วัตถุดิบทั้งหมด</option>'+ingredients.map(x=>`<option value="${x.id}">${x.name}</option>`).join('');loadStockHistory();if(document.querySelector('#costing-center'))renderCostingCenter();
}loadData();
