function openEditOrder(column,index){orderEditTarget={column,index};const x=orders[column][1][index],detail=x[9]||{},type=x[6]||'DINE_IN',items=x[8]?.length?x[8]:String(x[2]).split(',').map(part=>{const name=part.split('×')[0].trim(),menu=recipes.find(r=>r.name===name);return{recipe_id:menu?.recipe_id||menu?.id,menu_name:name,quantity:+(part.split('×')[1]||1),unit_price:channelPrice(menu||{})}});orderForm.reset();orderForm.elements.order_id.value=x[4]||`local-demo-${column}-${index}`;orderForm.elements.orderType.value=type;document.querySelector('#order-modal h2').textContent='แก้ไขออเดอร์';document.querySelector('#cancel-order').classList.remove('hidden');document.querySelectorAll('[data-order-type]').forEach(b=>b.classList.toggle('selected',b.dataset.orderType===type));renderChannelFields(type);const customer=orderForm.elements.customer;if(customer){if(type==='DINE_IN'&&![...customer.options].some(o=>o.value===x[7]))customer.add(new Option(x[7],x[7]));customer.value=x[7]||detail.customer||'';if(customer.selectedOptions[0])customer.selectedOptions[0].disabled=false}if(orderForm.elements.phone)orderForm.elements.phone.value=detail.phone||'';if(orderForm.elements.delivery_address)orderForm.elements.delivery_address.value=detail.delivery_address||'';orderForm.elements.note.value=detail.note||'';document.querySelector('#order-rows').innerHTML='';items.forEach(addOrderRow);showModal('order-modal')}
