async function openMenuForm(id){
 const form=document.querySelector('#menu-form');form.reset();document.querySelector('#recipe-rows').innerHTML='';let menu=recipes.find(x=>String(x.recipe_id||x.id)===String(id)),items=menu?.items||[];
 if(id&&Number.isInteger(+id)){try{const res=await fetch(`/api/recipes/${id}`);if(res.ok){const detail=await res.json();menu={...menu,...detail.recipe};items=detail.items}}catch{}}
 form.elements.id.value=id||'';form.elements.code.value=menu?.code||'';form.elements.name.value=menu?.name||'';form.elements.category.value=menu?.category||'เครื่องดื่ม';form.elements.price.value=menu?.selling_price||'';form.elements.online_price.value=menu?.online_selling_price||'';form.elements.serving.value=menu?.serving_size||'';
 if(menu?.category&&![...form.elements.category.options].some(option=>option.value===menu.category)){form.elements.category.add(new Option(menu.category,menu.category));form.elements.category.value=menu.category}
 document.querySelector('#menu-modal-title').textContent=menu?'แก้ไขเมนูและสูตร':'เพิ่มเมนูและสูตร';document.querySelector('#delete-menu').classList.toggle('hidden',!menu);
 if(items.length)items.forEach(item=>addRecipeRow(item));else addRecipeRow();showModal('menu-modal');
}
