function openStockForm(id){
 const form=document.querySelector('#stock-form'),item=ingredients.find(x=>String(x.id)===String(id));form.reset();
 if(item?.category&&![...form.elements.category.options].some(o=>o.value===item.category))form.elements.category.add(new Option(item.category,item.category));
 form.elements.id.value=item?.id||'';form.elements.sku.value=item?.sku||'';form.elements.barcode.value=item?.barcode||'';form.elements.name.value=item?.name||'';form.elements.category.value=item?.category||'วัตถุดิบ';form.elements.purchase_unit.value=item?.purchase_unit||'';form.elements.quantity_per_purchase.value=item?(+item.purchase_qty||1)*(+item.conversion_to_base||1):'';form.elements.purchase_price.value=item?.purchase_price||'';form.elements.base_unit.value=item?.base_unit||'';form.elements.reorder_level.value=item?.reorder_level||0;form.elements.supplier.value=item?.supplier||'';form.elements.expiry_date.value=item?.expiry_date?String(item.expiry_date).slice(0,10):'';
 document.querySelector('#current-stock-value').textContent=`${money(item?.stock_qty||0)} ${item?.base_unit||''}`;updateUnitCostPreview();
 document.querySelector('#stock-modal-title').textContent=item?'แก้ไขวัตถุดิบ':'เพิ่มวัตถุดิบ';document.querySelector('#delete-stock').classList.toggle('hidden',!item);showModal('stock-modal');
}
