function refreshStockOptions(){const select=document.querySelector('#adjust-ingredient');if(select)select.innerHTML=ingredients.map(x=>`<option value="${x.id}">${x.name} — คงเหลือ ${money(x.stock_qty)} ${x.base_unit}</option>`).join('')}
document.querySelector('#stock-form').onsubmit=async e=>{
 e.preventDefault();const fd=new FormData(e.target),id=fd.get('id'),payload={sku:fd.get('sku').trim(),barcode:fd.get('barcode').trim(),name:fd.get('name').trim(),category:fd.get('category'),purchase_unit:fd.get('purchase_unit').trim(),purchase_qty:+fd.get('quantity_per_purchase'),purchase_price:+fd.get('purchase_price'),base_unit:fd.get('base_unit').trim(),conversion_to_base:1,reorder_level:+fd.get('reorder_level'),supplier:fd.get('supplier').trim(),expiry_date:fd.get('expiry_date')||null},method=id?'PUT':'POST',url=id?`/api/ingredients/${id}`:'/api/ingredients';let saved;
 try{const res=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(res.ok)saved=await res.json()}catch{}
 if(!saved){toast('บันทึกวัตถุดิบไม่ได้ กรุณาตรวจสอบฐานข้อมูล');return}
 const cost=payload.purchase_price/(payload.purchase_qty*payload.conversion_to_base),index=ingredients.findIndex(x=>String(x.id)===String(id));
 if(saved){const merged={...saved,stock_qty:index>=0?ingredients[index].stock_qty:0,cost_per_base_unit:cost};if(index>=0)ingredients[index]=merged;else ingredients.push(merged)}
 else if(index>=0)ingredients[index]={...ingredients[index],...payload,cost_per_base_unit:cost};
 else ingredients.push({id:`local-stock-${Date.now()}`,...payload,stock_qty:0,cost_per_base_unit:cost});
 syncLocalStock();renderIngredients();closeModal(document.querySelector('#stock-modal'));toast(id?'แก้ไขวัตถุดิบเรียบร้อยแล้ว ✓':'เพิ่มวัตถุดิบเรียบร้อยแล้ว ✓');
};
function updateUnitCostPreview(){const form=document.querySelector('#stock-form'),price=+form.elements.purchase_price.value||0,qty=+form.elements.quantity_per_purchase.value||0,unit=form.elements.base_unit.value||'หน่วย';document.querySelector('#cost-unit').textContent=unit;document.querySelector('#unit-cost-value').textContent=`฿${qty?(price/qty).toFixed(4):'0.0000'}`}
