function menuOptions(){return recipes.map((x,i)=>x.sold_out?'':`<option value="${i}">${x.name} — ฿${money(channelPrice(x))}</option>`).join('')}
function renderChannelFields(type){
 const box=document.querySelector('#channel-fields');
 if(type==='DINE_IN')box.innerHTML=`<label>เลือกโต๊ะ<select name="customer" required>${restaurantTables.filter(t=>t.status!=='DISABLED').map(t=>`<option ${t.status==='OCCUPIED'?'disabled':''}>${t.name} · ${t.seats} ที่นั่ง${t.status==='OCCUPIED'?' (ไม่ว่าง)':''}</option>`).join('')}</select></label><label>จำนวนลูกค้า<input name="guest_count" type="number" min="1" value="2"></label><div class="channel-hint">🍽️ ออเดอร์จะส่งเข้าคิวครัวและผูกกับโต๊ะที่เลือก</div>`;
 if(type==='TAKEAWAY')box.innerHTML=`<label>ชื่อลูกค้า<input name="customer" required placeholder="ชื่อสำหรับเรียกรับอาหาร"></label><label>เวลานัดรับ<input name="requested_at" type="datetime-local"></label><label>เบอร์โทร<input name="phone" type="tel" placeholder="08x-xxx-xxxx"></label><div class="channel-hint">🥡 ระบบจะแสดงออเดอร์ในคิวซื้อกลับหน้าร้าน</div>`;
 if(type==='DELIVERY')box.innerHTML=`<label>ชื่อลูกค้า<input name="customer" required></label><label>เบอร์โทร<input name="phone" type="tel" required placeholder="08x-xxx-xxxx"></label><label style="grid-column:1/-1">ที่อยู่จัดส่ง<input name="delivery_address" required placeholder="บ้านเลขที่ ถนน แขวง/ตำบล เขต/อำเภอ"></label><label>เวลาจัดส่ง<input name="requested_at" type="datetime-local"></label><div class="channel-hint">🛵 โปรดตรวจสอบเบอร์โทรและที่อยู่ก่อนยืนยัน</div>`;
}
function addOrderRow(orderItem){
 const row=document.createElement('div');row.className='order-item-row';row.innerHTML=`<label>เมนู<select class="order-menu-select">${menuOptions()}</select></label><label>จำนวน<input class="order-qty" type="number" min="1" value="${orderItem?.quantity||1}"></label><div class="line-total">฿0.00</div><button type="button" aria-label="ลบ">×</button>`;
 const menuIndex=recipes.findIndex(x=>String(x.recipe_id||x.id)===String(orderItem?.recipe_id)||x.name===orderItem?.menu_name);if(menuIndex>=0)row.querySelector('select').value=menuIndex;
 row.querySelector('button').onclick=()=>{row.remove();if(!document.querySelector('.order-item-row'))addOrderRow();updateOrderTotal()};row.querySelectorAll('select,input').forEach(x=>x.oninput=updateOrderTotal);document.querySelector('#order-rows').append(row);updateOrderTotal();
}
