 recipes=recipes.filter(x=>String(x.recipe_id||x.id)!==String(id));syncLocalMenus();renderRecipes();refreshOptions();closeModal(document.querySelector('#menu-modal'));toast('ลบเมนูเรียบร้อยแล้ว');
