// Purchase Order
let purchaseOrders=JSON.parse(localStorage.getItem('triplep_purchase_orders')||'[]');
function refreshPurchaseOptions(){const options=ingredients.map(x=>`<option value="${x.id}">${x.name} — ${x.purchase_unit||x.base_unit}</option>`).join('');document.querySelector('#po-ingredient').innerHTML=options;document.querySelector('#production-output').innerHTML=options;document.querySelector('#production-input').innerHTML=options;updatePoPrice()}
function updatePoPrice(){const item=ingredients.find(x=>String(x.id)===String(document.querySelector('#po-ingredient').value));if(item)document.querySelector('#po-form').elements.unit_price.value=item.purchase_price||0;updatePoTotal()}
function updatePoTotal(){const f=document.querySelector('#po-form');document.querySelector('#po-total').textContent=`฿${money((+f.elements.quantity.value||0)*(+f.elements.unit_price.value||0))}`}
async function loadPurchaseOrders(){try{const r=await fetch('/api/purchase-orders');if(r.ok)purchaseOrders=await r.json()}catch{}renderPurchaseOrders()}
function renderPurchaseOrders(){document.querySelector('#purchase-orders').innerHTML=purchaseOrders.length?purchaseOrders.map(p=>`<tr><td><strong>${p.po_number}</strong><small class="stock-sub">${p.invoice_number?`ใบส่งของ ${p.invoice_number}`:''}</small></td><td>${p.supplier}</td><td>${p.received_at?new Date(p.received_at).toLocaleString('th-TH'):p.expected_date?new Date(p.expected_date).toLocaleDateString('th-TH'):'-'}</td><td>฿${money(p.total)}</td><td><span class="pill ${p.status==='RECEIVED'?'':'low'}">${p.status==='RECEIVED'?'รับแล้ว':'รอรับ'}</span>${p.received_by?`<small class="stock-sub">โดย ${p.received_by}</small>`:''}</td><td>${p.status!=='RECEIVED'?`<button class="status-action receive-po" data-id="${p.id}">รับสินค้า</button>`:''}</td></tr>`).join(''):'<tr><td colspan="6">ยังไม่มีใบสั่งซื้อ</td></tr>';document.querySelector('#po-pending').textContent=purchaseOrders.filter(x=>x.status==='PENDING').length;document.querySelector('#po-approved').textContent=purchaseOrders.filter(x=>x.status!=='RECEIVED').length;document.querySelector('#po-value').textContent=`฿${money(purchaseOrders.reduce((s,x)=>s+(+x.total||0),0))}`;document.querySelectorAll('.receive-po').forEach(b=>b.onclick=()=>receivePo(b.dataset.id))}
document.querySelector('#new-po').onclick=()=>{refreshPurchaseOptions();showModal('po-modal')};document.querySelector('#po-ingredient').onchange=updatePoPrice;document.querySelector('#po-form').elements.quantity.oninput=updatePoTotal;document.querySelector('#po-form').elements.unit_price.oninput=updatePoTotal;
document.querySelector('#po-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),payload={supplier:f.get('supplier'),expected_date:f.get('expected_date'),ingredient_id:f.get('ingredient_id'),quantity:+f.get('quantity'),unit_price:+f.get('unit_price'),note:f.get('note')};let saved;try{const r=await fetch('/api/purchase-orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(r.ok)saved=await r.json()}catch{}purchaseOrders.unshift(saved||{id:`local-po-${Date.now()}`,po_number:`PO-${Date.now().toString().slice(-6)}`,status:'PENDING',total:payload.quantity*payload.unit_price,...payload});localStorage.setItem('triplep_purchase_orders',JSON.stringify(purchaseOrders));renderPurchaseOrders();closeModal(document.querySelector('#po-modal'));e.target.reset();toast('สร้างใบสั่งซื้อเรียบร้อยแล้ว ✓')};
async function receivePoLegacy(id){const po=purchaseOrders.find(x=>String(x.id)===String(id));let received=false;try{const r=await fetch(`/api/purchase-orders/${id}/receive`,{method:'POST'});received=r.ok}catch{}if(!received&&!String(id).startsWith('local-')){toast('ยังรับสินค้าไม่ได้ กรุณาตรวจสอบฐานข้อมูล');return}if(!received){const item=ingredients.find(x=>String(x.id)===String(id));if(item)item.stock_qty+=po.quantity*(item.purchase_qty||1)*(item.conversion_to_base||1);syncLocalStock()}po.status='RECEIVED';localStorage.setItem('triplep_purchase_orders',JSON.stringify(purchaseOrders));renderPurchaseOrders();renderIngredients();toast('รับสินค้าเข้าสต็อกแล้ว ✓')}

// Production batches
let productionBatches=JSON.parse(localStorage.getItem('triplep_production')||'[]');
async function loadProduction(){try{const r=await fetch('/api/production');if(r.ok)productionBatches=await r.json()}catch{}renderProduction()}
function renderProduction(){document.querySelector('#production-batches').innerHTML=productionBatches.length?productionBatches.map(b=>`<tr><td><strong>${b.batch_code}</strong></td><td>${b.output_name||ingredients.find(x=>String(x.id)===String(b.output_ingredient_id))?.name||'-'}</td><td>${money(b.output_qty)} ${b.output_unit||''}</td><td>${b.input_name||ingredients.find(x=>String(x.id)===String(b.input_ingredient_id))?.name||'-'} · ${money(b.input_qty)}</td><td>฿${money(b.total_cost)}</td><td>${new Date(b.produced_at||Date.now()).toLocaleString('th-TH')}</td></tr>`).join(''):'<tr><td colspan="6">ยังไม่มีรายการผลิต</td></tr>';document.querySelector('#batch-count').textContent=productionBatches.length;document.querySelector('#batch-output').textContent=money(productionBatches.reduce((s,x)=>s+(+x.output_qty||0),0));document.querySelector('#batch-cost').textContent=`฿${money(productionBatches.reduce((s,x)=>s+(+x.total_cost||0),0))}`}
document.querySelector('#new-production').onclick=()=>{refreshPurchaseOptions();showModal('production-modal')};
document.querySelector('#production-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),payload={batch_code:f.get('batch_code'),output_ingredient_id:f.get('output_ingredient_id'),output_qty:+f.get('output_qty'),input_ingredient_id:f.get('input_ingredient_id'),input_qty:+f.get('input_qty'),note:f.get('note')},input=ingredients.find(x=>String(x.id)===String(payload.input_ingredient_id));if(payload.input_qty>+input.stock_qty){toast('วัตถุดิบไม่เพียงพอสำหรับการผลิต');return}let saved;try{const r=await fetch('/api/production',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(r.ok)saved=await r.json()}catch{}const cost=payload.input_qty*(+input.cost_per_base_unit||0);productionBatches.unshift(saved||{id:`local-batch-${Date.now()}`,produced_at:new Date().toISOString(),total_cost:cost,...payload});if(!saved){input.stock_qty-=payload.input_qty;const output=ingredients.find(x=>String(x.id)===String(payload.output_ingredient_id));output.stock_qty+=payload.output_qty;syncLocalStock()}localStorage.setItem('triplep_production',JSON.stringify(productionBatches));renderProduction();renderIngredients();closeModal(document.querySelector('#production-modal'));e.target.reset();toast('บันทึก Batch การผลิตแล้ว ✓')};

// Profit analysis
function renderProfitAnalysis(){const avg=recipes.length?recipes.reduce((s,x)=>s+(+x.food_cost_pct||0),0)/recipes.length:0,online=recipes.length?recipes.reduce((s,x)=>s+(+x.online_profit||0),0)/recipes.length:0,total=recipes.reduce((s,x)=>s+(+x.gross_profit||0)*10,0);document.querySelector('#profit-total').textContent=`฿${money(total)}`;document.querySelector('#food-cost-average').textContent=`${money(avg)}%`;document.querySelector('#online-profit-average').textContent=`฿${money(online)}`;const max=Math.max(...recipes.map(x=>+x.gross_profit||0),1);document.querySelector('#profit-bars').innerHTML='<h3>กำไรต่อเมนู</h3>'+recipes.map(x=>`<div class="profit-bar"><strong>${x.name}</strong><span><i style="width:${Math.max(3,(+x.gross_profit||0)/max*100)}%"></i></span><b>฿${money(x.gross_profit)}</b></div>`).join('')}
async function loadSalesReport(){
 const period=document.querySelector('#report-period').value;let data;
 try{const r=await fetch(`/api/reports/sales?period=${period}`);if(r.ok)data=await r.json()}catch{}
 if(!data){const now=new Date(),sales=JSON.parse(localStorage.getItem('triplep_completed_sales')||'[]').filter(x=>{const d=new Date(x.completed_at);if(period==='today')return d.toDateString()===now.toDateString();if(period==='7days')return now-d<=7*864e5;if(period==='month')return d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear();return true}),store=sales.filter(x=>x.order_type!=='DELIVERY'),online=sales.filter(x=>x.order_type==='DELIVERY');data={totals:{total:sales.reduce((s,x)=>s+x.total,0),order_count:sales.length,store_sales:store.reduce((s,x)=>s+x.total,0),store_count:store.length,online_sales:online.reduce((s,x)=>s+x.total,0),online_count:online.length},payments:['CASH','QR','CARD'].map(m=>({payment_method:m,total:sales.filter(x=>x.payment_method===m).reduce((s,x)=>s+x.total,0),count:sales.filter(x=>x.payment_method===m).length}))}}
 const t=data.totals,pay=Object.fromEntries(data.payments.map(x=>[x.payment_method||'UNKNOWN',x]));document.querySelector('#report-sales-total').textContent=`฿${money(t.total)}`;document.querySelector('#report-order-count').textContent=t.order_count;document.querySelector('#report-store-sales').textContent=`฿${money(t.store_sales)}`;document.querySelector('#report-store-count').textContent=`${t.store_count} บิล`;document.querySelector('#report-online-sales').textContent=`฿${money(t.online_sales)}`;document.querySelector('#report-online-count').textContent=`${t.online_count} บิล`;
 for(const [key,id] of [['CASH','cash'],['QR','qr'],['CARD','card']]){document.querySelector(`#payment-${id}`).textContent=`฿${money(pay[key]?.total||0)}`;document.querySelector(`#payment-${id}-count`).textContent=`${pay[key]?.count||0} รายการ`}
 const share=+t.total?Math.round(+t.store_sales/+t.total*100):0;document.querySelector('#sales-donut').style.setProperty('--store-share',`${share}%`);document.querySelector('#store-percent').textContent=`${share}%`;document.querySelector('#legend-store').textContent=`฿${money(t.store_sales)}`;document.querySelector('#legend-online').textContent=`฿${money(t.online_sales)}`;
 const avgMargin=recipes.length?recipes.reduce((s,x)=>s+(1-(+x.food_cost_pct||0)/100),0)/recipes.length:0;document.querySelector('#profit-total').textContent=`฿${money(+t.total*avgMargin)}`;
}
document.querySelector('#report-period').onchange=loadSalesReport;

// Store settings
let storeSettings=JSON.parse(localStorage.getItem('triplep_settings')||'null')||{store_name:'Triple P Brew',vat_rate:0,service_charge:0,online_gp:35,currency:'THB',promptpay_type:'PHONE',receipt_prefix:'TPP',receipt_footer:'ขอบคุณที่ใช้บริการ',opening_time:'08:00',closing_time:'18:00',food_cost_target:35,low_stock_alert:true};
function applyStoreSettings(){document.querySelector('.brand strong').textContent=storeSettings.store_name.toUpperCase();document.title=`${storeSettings.store_name} — Restaurant & Café Manager`;const target=document.querySelector('#food-cost-average')?.nextElementSibling;if(target)target.textContent=`เป้าหมายไม่เกิน ${money(storeSettings.food_cost_target)}%`;document.querySelector('#online-profit-average')?.nextElementSibling&&(document.querySelector('#online-profit-average').nextElementSibling.textContent=`หลังหัก GP ${money(storeSettings.online_gp)}%`)}
function fillSettingsForm(){const form=document.querySelector('#settings-form');Object.entries(storeSettings).forEach(([k,v])=>{if(!form.elements[k])return;if(form.elements[k].type==='checkbox')form.elements[k].checked=!!v;else form.elements[k].value=v??''});applyStoreSettings()}
async function loadSettings(){try{const r=await fetch('/api/settings');if(r.ok)storeSettings=await r.json()}catch{}fillSettingsForm();if(document.querySelector('#costing-center'))renderCostingCenter()}
document.querySelector('#settings-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),payload={store_name:f.get('store_name'),tax_id:f.get('tax_id'),phone:f.get('phone'),email:f.get('email'),address:f.get('address'),vat_rate:+f.get('vat_rate'),service_charge:+f.get('service_charge'),online_gp:+f.get('online_gp'),currency:f.get('currency'),promptpay_type:f.get('promptpay_type'),promptpay_id:f.get('promptpay_id'),receipt_prefix:f.get('receipt_prefix'),receipt_footer:f.get('receipt_footer'),opening_time:f.get('opening_time'),closing_time:f.get('closing_time'),food_cost_target:+f.get('food_cost_target'),low_stock_alert:e.target.elements.low_stock_alert.checked};let saved;try{const r=await fetch('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(r.ok)saved=await r.json()}catch{}storeSettings=saved||payload;localStorage.setItem('triplep_settings',JSON.stringify(storeSettings));applyStoreSettings();document.querySelector('#settings-status').textContent=`บันทึกล่าสุด: ${new Date().toLocaleTimeString('th-TH')}`;renderProfitAnalysis();toast('บันทึกการตั้งค่าร้านแล้ว ✓')};

// QR / Barcode scanner
let scannerStream,scannerTimer;
document.querySelector('#scan-barcode').onclick=startScanner;document.querySelector('#stop-scanner').onclick=stopScanner;
async function startScanner(){showModal('scanner-modal');const status=document.querySelector('#scanner-status');try{scannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const video=document.querySelector('#scanner-video');video.srcObject=scannerStream;if('BarcodeDetector'in window){const detector=new BarcodeDetector({formats:['qr_code','ean_13','ean_8','code_128','code_39']});scannerTimer=setInterval(async()=>{try{const codes=await detector.detect(video);if(codes[0]){const value=codes[0].rawValue,statusItem=ingredients.find(x=>x.barcode===value);status.textContent=statusItem?`พบ: ${statusItem.name}`:`Barcode: ${value}`;stopScanner();if(statusItem)openStockForm(statusItem.id);else{openStockForm();document.querySelector('#stock-form').elements.barcode.value=value}}}catch{}},500)}else status.textContent='เบราว์เซอร์นี้ยังไม่รองรับการอ่าน Barcode อัตโนมัติ'}catch{status.textContent='ไม่สามารถเปิดกล้องได้ โปรดตรวจสอบสิทธิ์กล้อง'}}
function stopScanner(){clearInterval(scannerTimer);scannerStream?.getTracks().forEach(t=>t.stop());scannerStream=null;closeModal(document.querySelector('#scanner-modal'))}
document.querySelector('[data-close="scanner-modal"]').onclick=stopScanner;
loadPurchaseOrders();loadProduction();loadSettings();renderProfitAnalysis();loadSalesReport();refreshPurchaseOptions();

// Daily stock count and remote owner control
let dailyCounts=[];
let dailyControlRows=[];
function setupDailyControl(){
 const stockActions=document.querySelector('#stock .view-actions');stockActions.insertAdjacentHTML('afterbegin','<button class="secondary" id="daily-count">✓ ตรวจนับปิดวัน</button>');
 const historyHead=document.querySelector('#stock .stock-history-head');historyHead.insertAdjacentHTML('beforebegin',`<div class="stock-history-head"><div><h3>ผลตรวจนับวันนี้</h3><p>เปรียบเทียบยอดตามระบบกับยอดที่นับจริง และปรับยอดให้อัตโนมัติ</p></div></div><div class="history-summary"><article><small>ตรวจนับแล้ว</small><strong id="count-total">0 รายการ</strong></article><article><small>ตรงกับระบบ</small><strong class="history-in" id="count-matched">0 รายการ</strong></article><article><small>มูลค่าส่วนต่าง</small><strong class="history-waste" id="count-variance">฿0.00</strong></article></div><div class="panel table-panel"><table><thead><tr><th>วัตถุดิบ</th><th>ตามระบบ</th><th>นับจริง</th><th>ส่วนต่าง</th><th>มูลค่า</th><th>ผู้ตรวจ</th><th>เหตุผล</th></tr></thead><tbody id="daily-counts"></tbody></table></div>`);
 historyHead.insertAdjacentHTML('beforebegin',`<div class="daily-control-block"><div class="stock-history-head"><div><h3>ควบคุมวัตถุดิบรายวัน</h3><p>Opening Stock → Receive → Sales → Waste → Closing Stock</p></div><div class="history-filters"><input type="date" id="daily-control-date"><input id="daily-control-search" placeholder="ค้นหาวัตถุดิบ"></div></div><div class="daily-control-summary"><article><small>ตรวจนับแล้ว</small><strong id="daily-control-counted">0 / 0</strong></article><article><small>รายการมีส่วนต่าง</small><strong id="daily-control-exceptions">0</strong></article><article><small>มูลค่าส่วนต่าง</small><strong id="daily-control-value">฿0.00</strong></article></div><div class="daily-control-note">ส่วนต่างอาจเกิดจากการตักเกินสูตร ของเสียที่ไม่ได้บันทึก หรือการรับสินค้าไม่ครบ ควรตรวจสอบรายการเคลื่อนไหวก่อนสรุปสาเหตุ</div><div class="panel table-panel"><table class="daily-control-table"><thead><tr><th>วัตถุดิบ</th><th>ยอดยกมา</th><th>รับเข้า</th><th>ใช้ตามยอดขาย</th><th>เบิกใช้อื่น</th><th>ของเสีย</th><th>ปรับยอด</th><th>ควรเหลือ</th><th>นับจริง</th><th>ส่วนต่าง</th><th>สถานะ</th></tr></thead><tbody id="daily-control-body"></tbody></table></div></div>`);
 document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="count-modal" aria-hidden="true"><form class="modal-card form-modal small-modal" id="count-form"><button type="button" class="close" id="close-count-modal">×</button><span class="modal-icon">✓</span><h2>ตรวจนับสต็อกปิดวัน</h2><p>กรอกยอดที่นับจริง ระบบจะบันทึกส่วนต่างและปรับยอดคงเหลือ</p><div class="form-grid"><label>วัตถุดิบ<select name="ingredient_id" id="count-ingredient" required></select></label><label>ยอดตามระบบ<input id="count-expected" readonly></label><label>ยอดที่นับจริง<input name="actual_qty" type="number" min="0" step=".001" required></label><label>ผู้ตรวจนับ<input name="counted_by" required placeholder="ชื่อพนักงาน"></label><label style="grid-column:1/-1">เหตุผลเมื่อมีส่วนต่าง<input name="reason" placeholder="เช่น ตักเกินสูตร, ของเสียไม่ได้บันทึก, รับสินค้าไม่ครบ"></label></div><button class="primary full" type="submit">บันทึกผลตรวจนับ</button></form></div>`);
 const reports=document.querySelector('#reports');reports.insertAdjacentHTML('afterbegin',`<div class="owner-daily"><div class="owner-daily-head"><div><span>OWNER CONTROL</span><h2>สรุปควบคุมร้านวันนี้</h2><p>ยอดขาย ต้นทุน ของเสีย ส่วนต่าง และรายการสั่งซื้อในหน้าเดียว</p></div><button class="secondary" id="refresh-owner-report">↻ อัปเดต</button></div><div class="owner-metrics"><article><small>ยอดขายวันนี้</small><strong id="owner-sales">฿0</strong><p id="owner-orders">0 บิล</p></article><article><small>อาหาร / เครื่องดื่ม</small><strong id="owner-units">0 / 0</strong><p>จานหรือชาม / แก้ว</p></article><article><small>ต้นทุนตามสูตร</small><strong id="owner-cost">฿0</strong><p id="owner-cost-pct">0% ของยอดขาย</p></article><article><small>ของเสียวันนี้</small><strong id="owner-waste">฿0</strong><p id="owner-waste-count">0 รายการ</p></article><article><small>ส่วนต่างตรวจนับ</small><strong id="owner-variance">฿0</strong><p id="owner-counted">ตรวจแล้ว 0 รายการ</p></article></div><div class="owner-reorder"><h3>รายการต้องสั่งซื้อ</h3><div id="owner-reorder-list"><p>กำลังโหลด...</p></div></div></div>`);
 document.querySelector('#daily-count').onclick=openDailyCount;document.querySelector('#close-count-modal').onclick=()=>closeModal(document.querySelector('#count-modal'));document.querySelector('#count-modal').onclick=e=>{if(e.target.id==='count-modal')closeModal(e.target)};document.querySelector('#count-ingredient').onchange=updateCountExpected;document.querySelector('#count-form').onsubmit=saveDailyCount;document.querySelector('#refresh-owner-report').onclick=loadOwnerControl;
 const today=new Date(),dateInput=document.querySelector('#daily-control-date');dateInput.value=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;dateInput.insertAdjacentHTML('afterend','<select id="daily-control-group"><option value="">ทุกกลุ่ม</option><option value="A">A · ของสด</option><option value="B">B · ของแช่เย็น</option><option value="C">C · ของแห้ง</option><option value="D">D · บรรจุภัณฑ์</option></select>');dateInput.onchange=loadDailyControl;document.querySelector('#daily-control-group').onchange=renderDailyControl;document.querySelector('#daily-control-search').oninput=renderDailyControl;loadDailyCounts();loadDailyControl();loadOwnerControl();
}
function openDailyCount(){const select=document.querySelector('#count-ingredient');select.innerHTML=ingredients.map(x=>`<option value="${x.id}">${x.name} — ${money(x.stock_qty)} ${x.base_unit}</option>`).join('');document.querySelector('#count-form').reset();updateCountExpected();showModal('count-modal')}
function updateCountExpected(){const item=ingredients.find(x=>String(x.id)===String(document.querySelector('#count-ingredient').value));document.querySelector('#count-expected').value=item?`${money(item.stock_qty)} ${item.base_unit}`:'-'}
function renderDailyCounts(){document.querySelector('#daily-counts').innerHTML=dailyCounts.length?dailyCounts.map(x=>`<tr><td><strong>${x.name}</strong><small class="stock-sub">${x.sku}</small></td><td>${money(x.expected_qty)} ${x.base_unit}</td><td>${money(x.actual_qty)} ${x.base_unit}</td><td class="${+x.variance_qty===0?'':+x.variance_qty>0?'up':'down'}">${+x.variance_qty>0?'+':''}${money(x.variance_qty)} ${x.base_unit}</td><td>฿${money(Math.abs(+x.variance_value||0))}</td><td>${x.counted_by}</td><td>${x.reason||'-'}</td></tr>`).join(''):'<tr><td colspan="7">ยังไม่มีการตรวจนับวันนี้</td></tr>';document.querySelector('#count-total').textContent=`${dailyCounts.length} รายการ`;document.querySelector('#count-matched').textContent=`${dailyCounts.filter(x=>+x.variance_qty===0).length} รายการ`;document.querySelector('#count-variance').textContent=`฿${money(dailyCounts.reduce((s,x)=>s+Math.abs(+x.variance_value||0),0))}`}
async function loadDailyCounts(){try{const r=await fetch('/api/stock/counts');if(r.ok)dailyCounts=await r.json()}catch{}renderDailyCounts()}
async function loadDailyControl(){const date=document.querySelector('#daily-control-date')?.value||'';try{const r=await fetch(`/api/stock/daily-control${date?`?date=${date}`:''}`);if(r.ok)dailyControlRows=await r.json()}catch{}renderDailyControl()}
function renderDailyControl(){const q=(document.querySelector('#daily-control-search')?.value||'').toLowerCase(),group=document.querySelector('#daily-control-group')?.value||'',rows=dailyControlRows.filter(x=>(!group||x.stock_group===group)&&(!q||`${x.name} ${x.sku}`.toLowerCase().includes(q)));document.querySelector('#daily-control-body').innerHTML=rows.map(x=>{const counted=x.actual_qty!==null&&x.actual_qty!==undefined,variance=+x.variance_qty||0,status=!counted?'รอตรวจนับ':variance===0?'ตรง':'ต้องตรวจสอบ',groupLabel={A:'ของสด',B:'แช่เย็น',C:'ของแห้ง',D:'บรรจุภัณฑ์'}[x.stock_group]||'';return `<tr class="${counted&&variance!==0?'daily-exception':''}"><td><strong><span class="stock-group group-${x.stock_group}">${x.stock_group}</span>${x.name}</strong><small class="stock-sub">${groupLabel} · ${x.sku} · ${x.base_unit}</small></td><td>${money(x.opening_qty)}</td><td class="up">+${money(x.received_qty)}</td><td>−${money(x.sales_usage_qty)}</td><td>−${money(x.other_usage_qty)}</td><td class="down">−${money(x.waste_qty)}</td><td>${+x.adjustment_qty>0?'+':''}${money(x.adjustment_qty)}</td><td><strong>${money(x.expected_closing_qty)}</strong></td><td>${counted?money(x.actual_qty):'-'}</td><td class="${!counted?'':variance===0?'':variance>0?'up':'down'}">${counted?`${variance>0?'+':''}${money(variance)}`:'-'}</td><td><span class="daily-status ${status==='ตรง'?'good':status==='ต้องตรวจสอบ'?'warn':'pending'}">${status}</span>${x.reason?`<small class="stock-sub">${x.reason}</small>`:''}</td></tr>`}).join('');const counted=rows.filter(x=>x.actual_qty!==null&&x.actual_qty!==undefined),exceptions=counted.filter(x=>+x.variance_qty!==0);document.querySelector('#daily-control-counted').textContent=`${counted.length} / ${rows.length}`;document.querySelector('#daily-control-exceptions').textContent=exceptions.length;document.querySelector('#daily-control-value').textContent=`฿${money(exceptions.reduce((s,x)=>s+(+x.variance_value||0),0))}`}
async function saveDailyCount(e){e.preventDefault();const f=new FormData(e.target),payload={ingredient_id:f.get('ingredient_id'),actual_qty:+f.get('actual_qty'),counted_by:f.get('counted_by').trim(),reason:f.get('reason').trim()};try{const r=await fetch('/api/stock/counts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw Error((await r.json()).error);await loadData();await Promise.all([loadDailyCounts(),loadDailyControl(),loadStockHistory(),loadOwnerControl()]);closeModal(document.querySelector('#count-modal'));toast('บันทึกผลตรวจนับและปรับยอดแล้ว ✓')}catch(error){toast(`บันทึกไม่ได้: ${error.message}`)}}
async function loadOwnerControl(){let data;try{const r=await fetch('/api/reports/daily-control');if(r.ok)data=await r.json()}catch{}if(!data)return;const s=data.sales,w=data.waste,c=data.counts;document.querySelector('#owner-sales').textContent=`฿${money(s.sales_total)}`;document.querySelector('#owner-orders').textContent=`${s.order_count} บิล`;document.querySelector('#owner-units').textContent=`${money(s.food_qty)} / ${money(s.drink_qty)}`;document.querySelector('#owner-cost').textContent=`฿${money(s.theoretical_cost)}`;document.querySelector('#owner-cost-pct').textContent=`${+s.sales_total?money(+s.theoretical_cost/+s.sales_total*100):'0.00'}% ของยอดขาย`;document.querySelector('#owner-waste').textContent=`฿${money(w.waste_value)}`;document.querySelector('#owner-waste-count').textContent=`${w.waste_count} รายการ`;document.querySelector('#owner-variance').textContent=`฿${money(c.variance_value)}`;document.querySelector('#owner-counted').textContent=`ตรวจแล้ว ${c.count_items} รายการ`;document.querySelector('#owner-reorder-list').innerHTML=data.reorder.length?data.reorder.map(x=>`<div class="reorder-item"><div><strong>${x.name}</strong><small>${x.supplier||'ยังไม่ระบุ Supplier'}</small></div><span>เหลือ ${money(x.stock_qty)} / ขั้นต่ำ ${money(x.reorder_level)} ${x.base_unit}</span></div>`).join(''):'<p class="all-good">✓ สต็อกทุกรายการสูงกว่าจุดสั่งซื้อ</p>'}
setupDailyControl();

// Excel-inspired costing workspace
let costingMode='ingredients',costingFilter='all',costingSearch='';
function setupCostingCenter(){
 const settingsNav=document.querySelector('.nav-item[data-view="settings"]');settingsNav.insertAdjacentHTML('beforebegin','<button class="nav-item" data-view="costing-center"><span>⌗</span> สูตรและต้นทุน <b class="nav-badge warn" id="costing-missing-badge">0</b></button>');
 const settingsView=document.querySelector('#settings');settingsView.insertAdjacentHTML('beforebegin',`<section id="costing-center" class="view"><div class="view-head costing-title"><div><span class="costing-eyebrow">COSTING WORKSPACE</span><h2>จัดการสูตรและต้นทุน</h2><p>ปรับราคาวัตถุดิบ สูตร และราคาขาย โดยคำนวณผลลัพธ์ให้อัตโนมัติ</p></div><button class="primary" id="costing-add-menu">＋ เพิ่มเมนูและสูตร</button></div><div class="costing-steps"><button class="active" data-costing-mode="ingredients"><b>1</b><span><strong>ราคาวัตถุดิบ</strong><small>ราคาและขนาดแพ็ก</small></span></button><button data-costing-mode="recipes"><b>2</b><span><strong>สูตรและราคาขาย</strong><small>ต้นทุนและกำไรต่อเมนู</small></span></button></div><div class="costing-kpis"><article><small>วัตถุดิบทั้งหมด</small><strong id="costing-ingredient-count">0</strong><p>รายการ</p></article><article class="costing-alert-card"><small>ยังไม่มีราคาซื้อ</small><strong id="costing-missing-count">0</strong><p>ควรกรอกก่อนเปิดขาย</p></article><article><small>เมนูทั้งหมด</small><strong id="costing-recipe-count">0</strong><p>สูตร</p></article><article><small>Food Cost เฉลี่ย</small><strong id="costing-average-fc">0%</strong><p id="costing-target-label">เป้าหมาย 35%</p></article></div><div class="costing-assumptions panel"><div><h3>สมมติฐานการคำนวณ</h3><p>ค่ากลางจากชีตตั้งค่าใน Excel</p></div><label>GP และ VAT ออนไลน์ (%)<input id="costing-online-gp" type="number" min="0" max="100" step=".1"></label><label>Food Cost เป้าหมาย (%)<input id="costing-food-target" type="number" min="1" max="100" step=".1"></label><button class="secondary" id="save-costing-settings">บันทึกสมมติฐาน</button></div><div id="costing-ingredients-panel"><div class="costing-toolbar"><label class="costing-search">⌕ <input id="costing-search" placeholder="ค้นหาวัตถุดิบหรือ SKU"></label><select id="costing-filter"><option value="all">วัตถุดิบทั้งหมด</option><option value="missing">เฉพาะที่ยังไม่มีราคา</option><option value="วัตถุดิบ">วัตถุดิบ</option><option value="บรรจุภัณฑ์">บรรจุภัณฑ์</option><option value="ค่าใช้จ่าย">ค่าใช้จ่าย</option></select><button class="secondary" id="costing-add-ingredient">＋ เพิ่มวัตถุดิบ</button></div><div class="panel table-panel"><table class="costing-table"><thead><tr><th>วัตถุดิบ</th><th>หมวด</th><th>ราคาซื้อ</th><th>ปริมาณต่อแพ็ก</th><th>หน่วยฐาน</th><th>ต้นทุนต่อหน่วย</th><th>Supplier / แหล่งข้อมูล</th><th></th></tr></thead><tbody id="costing-ingredients"></tbody></table></div></div><div id="costing-recipes-panel" class="hidden"><div class="costing-toolbar"><label class="costing-search">⌕ <input id="costing-recipe-search" placeholder="ค้นหาเมนู รหัส หรือหมวด"></label><span class="costing-hint">แก้ราคาแล้วกดบันทึก สูตรวัตถุดิบแก้ผ่านปุ่ม “แก้สูตร”</span></div><div class="panel table-panel"><table class="costing-table"><thead><tr><th>เมนู</th><th>ต้นทุนสูตร</th><th>ราคาหน้าร้าน</th><th>Food Cost</th><th>กำไรหน้าร้าน</th><th>ราคาออนไลน์</th><th>กำไรหลัง GP</th><th></th></tr></thead><tbody id="costing-recipes"></tbody></table></div></div></section>`);
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelectorAll('[data-costing-mode]').forEach(b=>b.onclick=()=>switchCostingMode(b.dataset.costingMode));document.querySelector('#costing-add-menu').onclick=()=>openMenuForm();document.querySelector('#costing-add-ingredient').onclick=()=>openStockForm();document.querySelector('#costing-search').oninput=e=>{costingSearch=e.target.value.toLowerCase();renderCostingIngredients()};document.querySelector('#costing-recipe-search').oninput=e=>{costingSearch=e.target.value.toLowerCase();renderCostingRecipes()};document.querySelector('#costing-filter').onchange=e=>{costingFilter=e.target.value;renderCostingIngredients()};document.querySelector('#save-costing-settings').onclick=saveCostingSettings;document.querySelector('#costing-ingredients').onclick=handleCostingIngredientClick;document.querySelector('#costing-recipes').onclick=handleCostingRecipeClick;renderCostingCenter();
}
function switchCostingMode(mode){costingMode=mode;costingSearch='';document.querySelectorAll('[data-costing-mode]').forEach(b=>b.classList.toggle('active',b.dataset.costingMode===mode));document.querySelector('#costing-ingredients-panel').classList.toggle('hidden',mode!=='ingredients');document.querySelector('#costing-recipes-panel').classList.toggle('hidden',mode!=='recipes');renderCostingCenter()}
function renderCostingCenter(){
 const missing=ingredients.filter(x=>+x.purchase_price===0).length,avg=recipes.length?recipes.reduce((s,x)=>s+(+x.food_cost_pct||0),0)/recipes.length:0;document.querySelector('#costing-ingredient-count').textContent=ingredients.length;document.querySelector('#costing-missing-count').textContent=missing;document.querySelector('#costing-missing-badge').textContent=missing;document.querySelector('#costing-missing-badge').style.display=missing?'':'none';document.querySelector('#costing-recipe-count').textContent=recipes.length;document.querySelector('#costing-average-fc').textContent=`${money(avg)}%`;document.querySelector('#costing-target-label').textContent=`เป้าหมาย ${money(storeSettings.food_cost_target||35)}%`;document.querySelector('#costing-online-gp').value=storeSettings.online_gp??32.1;document.querySelector('#costing-food-target').value=storeSettings.food_cost_target??35;if(costingMode==='ingredients')renderCostingIngredients();else renderCostingRecipes();
}
function renderCostingIngredients(){
 const header=document.querySelector('#costing-ingredients-panel thead tr');if(header&&!header.querySelector('[data-reorder-head]'))header.children[6].insertAdjacentHTML('beforebegin','<th data-reorder-head>จุดสั่งซื้อ</th>');
 const rows=ingredients.filter(x=>(costingFilter==='all'||costingFilter==='missing'&&+x.purchase_price===0||x.category===costingFilter)&&(!costingSearch||`${x.name} ${x.sku}`.toLowerCase().includes(costingSearch)));document.querySelector('#costing-ingredients').innerHTML=rows.length?rows.map(x=>`<tr class="${+x.purchase_price===0?'cost-row-missing':''}" data-cost-id="${x.id}"><td><strong>${x.name}</strong><small>${x.sku}</small></td><td><span class="cost-category">${x.category||'วัตถุดิบ'}</span></td><td><div class="money-input"><span>฿</span><input data-field="purchase_price" type="number" min="0" step=".01" value="${+x.purchase_price||0}"></div></td><td><input data-field="purchase_qty" class="cost-number-input" type="number" min=".001" step=".001" value="${+x.purchase_qty||1}"></td><td><input data-field="base_unit" class="cost-unit-input" value="${x.base_unit||''}"></td><td><strong class="calculated-cost">฿${(+x.purchase_qty?+x.purchase_price/(+x.purchase_qty*(+x.conversion_to_base||1)):0).toFixed(4)}</strong></td><td><input data-field="reorder_level" class="cost-number-input" type="number" min="0" step=".001" value="${+x.reorder_level||0}" title="จุดสั่งซื้อ"></td><td><input data-field="supplier" class="cost-source-input" value="${x.supplier||''}" placeholder="ระบุ Supplier"></td><td><button class="save-cost-row" data-id="${x.id}">บันทึก</button></td></tr>`).join(''):'<tr><td colspan="9" class="costing-empty">ไม่พบวัตถุดิบตามตัวกรอง</td></tr>';
 document.querySelectorAll('#costing-ingredients input[data-field]').forEach(input=>input.oninput=()=>{const tr=input.closest('tr'),price=+tr.querySelector('[data-field="purchase_price"]').value||0,qty=+tr.querySelector('[data-field="purchase_qty"]').value||0;tr.querySelector('.calculated-cost').textContent=`฿${qty?(price/qty).toFixed(4):'0.0000'}`});
 document.querySelectorAll('#costing-ingredients tr[data-cost-id]').forEach(tr=>{const item=ingredients.find(x=>String(x.id)===tr.dataset.costId);tr.children[1].insertAdjacentHTML('beforeend',`<select data-field="stock_group" class="stock-group-select"><option value="A" ${item.stock_group==='A'?'selected':''}>A · ของสด</option><option value="B" ${item.stock_group==='B'?'selected':''}>B · แช่เย็น</option><option value="C" ${item.stock_group==='C'?'selected':''}>C · ของแห้ง</option><option value="D" ${item.stock_group==='D'?'selected':''}>D · บรรจุภัณฑ์</option></select>`)});
}
function renderCostingRecipes(){
 const rows=recipes.filter(x=>!costingSearch||`${x.name} ${x.code} ${x.category}`.toLowerCase().includes(costingSearch));document.querySelector('#costing-recipes').innerHTML=rows.map(x=>{const fc=+x.selling_price?+x.recipe_cost/+x.selling_price*100:0,onlineNet=+x.online_selling_price*(1-(+storeSettings.online_gp||0)/100),warning=+x.selling_price===0?'ยังไม่กำหนดราคา':fc>(+storeSettings.food_cost_target||35)?'ต้นทุนเกินเป้า':'อยู่ในเป้า';return `<tr data-recipe-id="${x.recipe_id||x.id}"><td><strong>${x.name}</strong><small>${x.code} · ${x.category}</small></td><td><strong>฿${money(x.recipe_cost)}</strong></td><td><div class="money-input"><span>฿</span><input data-price="store" type="number" min="0" step="1" value="${+x.selling_price||0}"></div></td><td><span class="fc-status ${warning==='อยู่ในเป้า'?'good':'warn'}">${money(fc)}% · ${warning}</span></td><td class="up">฿${money((+x.selling_price||0)-(+x.recipe_cost||0))}</td><td><div class="money-input"><span>฿</span><input data-price="online" type="number" min="0" step="1" value="${+x.online_selling_price||0}"></div></td><td class="${onlineNet-(+x.recipe_cost||0)>=0?'up':'down'}">฿${money(onlineNet-(+x.recipe_cost||0))}</td><td><div class="cost-row-actions"><button class="edit-cost-recipe" data-id="${x.recipe_id||x.id}">แก้สูตร</button><button class="save-cost-recipe" data-id="${x.recipe_id||x.id}">บันทึกราคา</button></div></td></tr>`}).join('');
}
async function handleCostingIngredientClick(e){const button=e.target.closest('.save-cost-row');if(!button)return;const tr=button.closest('tr'),item=ingredients.find(x=>String(x.id)===button.dataset.id),stockGroup=tr.querySelector('[data-field="stock_group"]').value,cycles={A:[2,1],B:[5,1],C:[7,3],D:[21,7]}[stockGroup],payload={...item,purchase_price:+tr.querySelector('[data-field="purchase_price"]').value,purchase_qty:+tr.querySelector('[data-field="purchase_qty"]').value,base_unit:tr.querySelector('[data-field="base_unit"]').value.trim(),reorder_level:+tr.querySelector('[data-field="reorder_level"]').value,supplier:tr.querySelector('[data-field="supplier"]').value.trim(),stock_group:stockGroup,purchase_cycle_days:cycles[0],count_cycle_days:cycles[1],conversion_to_base:+item.conversion_to_base||1};button.disabled=true;try{const r=await fetch(`/api/ingredients/${item.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw Error();await loadData();loadReorderSuggestions();toast(`บันทึกกลุ่มและข้อมูล ${item.name} แล้ว ✓`)}catch{toast('บันทึกต้นทุนไม่ได้ กรุณาตรวจสอบเซิร์ฟเวอร์')}finally{button.disabled=false}}
async function handleCostingRecipeClick(e){const edit=e.target.closest('.edit-cost-recipe'),save=e.target.closest('.save-cost-recipe');if(edit)return openMenuForm(edit.dataset.id);if(!save)return;const tr=save.closest('tr'),id=save.dataset.id;save.disabled=true;try{const detail=await getRecipeDetail(id),menu=recipes.find(x=>String(x.recipe_id||x.id)===id),payload={code:menu.code,name:menu.name,category:menu.category,serving_size:menu.serving_size,selling_price:+tr.querySelector('[data-price="store"]').value,online_selling_price:+tr.querySelector('[data-price="online"]').value,items:detail.items.map((x,index)=>({ingredient_id:(detail.items[index].ingredient_id||ingredients.find(i=>i.name===x.name)?.id),qty_base:x.qty}))};const raw=await fetch(`/api/recipes/${id}`);if(raw.ok){const d=await raw.json();payload.items=d.items.map(x=>({ingredient_id:x.ingredient_id,qty_base:+x.qty_base}))}const r=await fetch(`/api/recipes/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw Error();await loadData();toast(`บันทึกราคา ${menu.name} แล้ว ✓`)}catch{toast('บันทึกราคาไม่ได้ กรุณาตรวจสอบข้อมูลสูตร')}finally{save.disabled=false}}
async function saveCostingSettings(){const payload={...storeSettings,online_gp:+document.querySelector('#costing-online-gp').value,food_cost_target:+document.querySelector('#costing-food-target').value};try{const r=await fetch('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw Error();storeSettings=await r.json();fillSettingsForm();renderCostingCenter();toast('บันทึกสมมติฐานต้นทุนแล้ว ✓')}catch{toast('บันทึกสมมติฐานไม่ได้')};}
async function saveAllCostingChanges(){
 const button=document.querySelector('#save-costing-all');button.disabled=true;
 try{
  const settingsPayload={...storeSettings,online_gp:+document.querySelector('#costing-online-gp').value,food_cost_target:+document.querySelector('#costing-food-target').value};
  const requests=[fetch('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(settingsPayload)})];
  for(const tr of document.querySelectorAll('#costing-ingredients tr[data-cost-id]')){
   const item=ingredients.find(x=>String(x.id)===tr.dataset.costId),stockGroup=tr.querySelector('[data-field="stock_group"]').value,cycles={A:[2,1],B:[5,1],C:[7,3],D:[21,7]}[stockGroup];
   const payload={...item,purchase_price:+tr.querySelector('[data-field="purchase_price"]').value,purchase_qty:+tr.querySelector('[data-field="purchase_qty"]').value,base_unit:tr.querySelector('[data-field="base_unit"]').value.trim(),reorder_level:+tr.querySelector('[data-field="reorder_level"]').value,supplier:tr.querySelector('[data-field="supplier"]').value.trim(),stock_group:stockGroup,purchase_cycle_days:cycles[0],count_cycle_days:cycles[1],conversion_to_base:+item.conversion_to_base||1};
   requests.push(fetch(`/api/ingredients/${item.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}));
  }
  for(const tr of document.querySelectorAll('#costing-recipes tr[data-recipe-id]')){
   const id=tr.dataset.recipeId,menu=recipes.find(x=>String(x.recipe_id||x.id)===id),raw=await fetch(`/api/recipes/${id}`);if(!raw.ok)throw Error();const detail=await raw.json();
   const payload={code:menu.code,name:menu.name,category:menu.category,serving_size:menu.serving_size,selling_price:+tr.querySelector('[data-price="store"]').value,online_selling_price:+tr.querySelector('[data-price="online"]').value,items:detail.items.map(x=>({ingredient_id:x.ingredient_id,qty_base:+x.qty_base}))};
   requests.push(fetch(`/api/recipes/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}));
  }
  const responses=await Promise.all(requests);if(responses.some(r=>!r.ok))throw Error();storeSettings=await responses[0].json();await loadData();loadReorderSuggestions();toast('บันทึกการเปลี่ยนแปลงทั้งหมดแล้ว ✓');
 }catch{toast('บันทึกไม่สำเร็จ กรุณาตรวจสอบข้อมูลแล้วลองใหม่')}finally{button.disabled=false}
}
setupCostingCenter();
document.querySelector('.costing-title').insertAdjacentHTML('beforeend','<button class="primary" id="save-costing-all">บันทึกการเปลี่ยนแปลง</button>');
document.querySelector('#save-costing-all').onclick=saveAllCostingChanges;
document.head.insertAdjacentHTML('beforeend','<style>#costing-center .save-cost-row,#costing-center .save-cost-recipe,#save-costing-settings{display:none}</style>');

// Receiving and automatic reorder workflow
let receiveTargetId=null;
function setupSupplyWorkflow(){
 const head=document.querySelector('#purchases .view-head');head.querySelector('button').insertAdjacentHTML('beforebegin','<button class="secondary" id="generate-auto-po">⚡ สร้าง PO จากจุดสั่งซื้อ</button>');head.insertAdjacentHTML('afterend',`<div class="panel reorder-suggestions"><div class="panel-head"><div><h3>รายการแนะนำให้สั่งซื้อ</h3><p>คำนวณจากยอดคงเหลือเทียบกับจุดสั่งซื้อ เป้าหมายเติมถึง 2 เท่าของขั้นต่ำ</p></div><button id="refresh-reorder">↻ อัปเดต</button></div><div id="reorder-suggestion-list" class="reorder-suggestion-list"><p>กำลังตรวจสอบสต็อก...</p></div></div>`);document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="receive-modal" aria-hidden="true"><form class="modal-card form-modal small-modal" id="receive-form"><button type="button" class="close" id="close-receive">×</button><span class="modal-icon">✓</span><h2>รับสินค้าเข้าสต็อก</h2><p id="receive-reference">ใบสั่งซื้อ</p><div class="form-grid"><label>จำนวนที่รับจริง<input name="quantity" type="number" min=".001" step=".001" required></label><label>ราคาซื้อจริง / หน่วย<input name="unit_price" type="number" min="0" step=".01" required></label><label>ผู้รับสินค้า<input name="received_by" required placeholder="ชื่อพนักงาน"></label><label>เลขใบส่งของ / ใบเสร็จ<input name="invoice_number" placeholder="INV-..."></label></div><button class="primary full">ยืนยันรับสินค้า</button></form></div>`);document.querySelector('#generate-auto-po').onclick=generateAutoPo;document.querySelector('#refresh-reorder').onclick=loadReorderSuggestions;document.querySelector('#close-receive').onclick=()=>closeModal(document.querySelector('#receive-modal'));document.querySelector('#receive-form').onsubmit=submitReceiving;loadReorderSuggestions();
}
async function loadReorderSuggestions(){let rows=[];try{const r=await fetch('/api/reorder/suggestions');if(r.ok)rows=await r.json()}catch{}document.querySelector('#reorder-suggestion-list').innerHTML=rows.length?rows.map(x=>`<div class="reorder-suggestion"><div><strong>${x.name}</strong><small>${x.supplier||'ยังไม่ระบุ Supplier'} · ${x.purchase_unit}</small></div><span>เหลือ <b>${money(x.stock_qty)}</b> / ขั้นต่ำ ${money(x.reorder_level)} ${x.base_unit}</span><em>แนะนำ ${money(x.suggested_quantity)} หน่วยซื้อ</em></div>`).join(''):'<p class="all-good">✓ ยังไม่มีวัตถุดิบที่ถึงจุดสั่งซื้อ</p>'}
async function generateAutoPo(){if(!confirm('สร้างใบสั่งซื้อสำหรับทุกรายการที่มี Supplier ราคา และถึงจุดสั่งซื้อ?'))return;try{const r=await fetch('/api/reorder/generate',{method:'POST'});if(!r.ok)throw Error();const created=await r.json();await loadPurchaseOrders();toast(`สร้าง PO อัตโนมัติ ${created.length} รายการแล้ว ✓`)}catch{toast('สร้าง PO อัตโนมัติไม่ได้')}}
async function receivePo(id){receiveTargetId=id;const po=purchaseOrders.find(x=>String(x.id)===String(id));document.querySelector('#receive-reference').textContent=`${po?.po_number||'ใบสั่งซื้อ'} · ${po?.supplier||''}`;const form=document.querySelector('#receive-form');form.reset();form.elements.quantity.value=po?.quantity||1;form.elements.unit_price.value=po?.unit_price||(+po?.total||0);showModal('receive-modal')}
async function submitReceiving(e){e.preventDefault();const f=new FormData(e.target),payload={quantity:+f.get('quantity'),unit_price:+f.get('unit_price'),received_by:f.get('received_by').trim(),invoice_number:f.get('invoice_number').trim()};try{const r=await fetch(`/api/purchase-orders/${receiveTargetId}/receive`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw Error();closeModal(document.querySelector('#receive-modal'));await Promise.all([loadPurchaseOrders(),loadData(),loadStockHistory(),loadOwnerControl(),loadReorderSuggestions()]);toast('รับสินค้าและอัปเดตต้นทุนจริงแล้ว ✓')}catch{toast('รับสินค้าไม่ได้ กรุณาตรวจสอบข้อมูล')}}
setupSupplyWorkflow();
